/*
 Problem: 2333. Minimum Sum of Squared Difference
 Language: cpp
 Runtime: 7 ms (91.06%)
 Memory: 119.3 MB (93.30%)
 Tags: Array, Binary Search, Greedy, Sorting, Heap (Priority Queue)
*/

class Solution {
public:
    long long minSumSquareDiff(vector<int>& nums1, vector<int>& nums2, int k1, int k2) {
        static int cnt[100001];
        memset(cnt, 0, sizeof(cnt));

        long long k = 1LL * k1 + k2, sum = 0;
        int mx = 0, n = nums1.size();

        for (int i = 0; i < n; ++i) {
            int d = abs(nums1[i] - nums2[i]);
            ++cnt[d];
            sum += d;
            if (d > mx) mx = d;
        }

        if (sum <= k) return 0;

        for (int i = mx; i > 0 && k; --i) {
            int take = min(k, 1LL * cnt[i]);
            cnt[i] -= take;
            cnt[i - 1] += take;
            k -= take;
        }

        long long ans = 0;
        for (int i = 1; i <= mx; ++i)
            ans += 1LL * i * i * cnt[i];

        return ans;
    }
};
